import{_ as t,c as s,o as e,ah as a}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"2、【二三子問】","description":"帛書易 - 2、【二三子問】","frontmatter":{"title":"2、【二三子問】","description":"帛書易 - 2、【二三子問】"},"headers":[],"relativePath":"classics/boshuyi/003.md","filePath":"classics/boshuyi/003.md"}'),o={name:"classics/boshuyi/003.md"};function _(c,p,i,r,n,l){return e(),s("div",null,[...p[0]||(p[0]=[a("<p>譯文：二三子問道：『【周易】屢次稱「龍」，龍的德行如何？』</p><p>孔子曰：「龍大矣！龍形遷叚徦、假格，賓於帝，俔神聖之德也。高上齊虖星辰日月而不晀曜、烑，能陽也。下淪窮深之淵而不昧，能陰也。上則風雨奉之，下淪則有天下之時。窮乎深淵則魚蛟先後之，水遊之物莫不隨從。陵處則雷電養之，風雨避向，鳥獸弗幹。」</p><p>譯文：孔子說：『龍偉大呀！龍體飛升而上，作上帝賓客，顯現神聖的德行。至高能上行於星辰日月之間而不光耀，有陽之能；至下而潛沒於深清之淵而不闇昧，有陰之能。上飛則有風雨贊助之，下潛則有天然的深淵容納之。行於深流，則有魚蛟之屬或為之先導，或為之後衛，水遊諸生物無不隨從。若處於高陵，則有雷神護養它，風雨迴避它，鳥獸不能侵犯。』</p><p>曰：「龍大矣。龍既能雲變，又能蛇變，又能魚變，飛鳥徵蟲，唯所欲化，而不失本形，神能之至也。□□□□□□□□□□□焉，又弗能察也。智者不能察其變，辯者不能察其美，至巧不能象其文，明目弗能察視也。□□焉。化昆昆、䖵蟲，神貴之容也。天下之貴物也。」</p><p>譯文：孔子說：『龍偉大呀！龍既能變為雲，又能變為蛇，又能變為魚。無論是飛鳥，還是行蟲，它都可以任意變化，但不會失去它本來的形體特徵，可謂神能至極了。龍之德性雖有至聖至智之人亦不能盡知。有智慧者不能明察龍的變化，能言善辯者不能詳言其華美，至為機巧者不能模擬其文采，視力至為明晰者也看不清楚。龍變化為昆蟲，具有神異尊貴的容貌，是天下之尊貴之物。』</p><p>曰：「龍大矣。商之馴?德也。曰稱身□□□□【易】□和，爵之曰君子。戒事敬命，精白柔和，而不諱賢，爵之曰夫子。或大或小，其方一也。至周□也，而名之曰君子。兼，『黃裳』近之矣。尊威精白堅強，行之不可撓也，『不習』近之矣。」</p><p>譯文：孔子說：『龍偉大呀！從外知內，龍具有遜順之德，平易溫和，可尊稱之為君子。龍之德，行事警惕戒備，嚴肅謹慎地執行命令，內心精明潔白，溫柔謙和，不排斥憎惡賢能，可尊稱之為夫子。龍變化萬殊，或大或小，但守其道則一，至為周備，可稱之為君子。龍德謙和，【坤】卦六五「黃裳」之意與之相近。龍德尊貴威嚴、精明潔白、堅強，行動不可阻撓，【坤】卦六二「不習」之意與之相近。</p><p>·【易】曰：「潛龍勿用。」孔子曰：「龍潛矣而不陽，時窒矣而不出，可謂潛矣。大人安佚矣而不朝，猒在廷，亦猶龍之潛也。其行滅而不可用也，故曰『潛龍勿用』。」</p><p>譯文：【乾】初九曰：『寢龍勿用。』孔子曰：『龍寢息而不動，時機室塞而不出，可以說是「寢息」了。大人安逸而不在朝任職，苟且隱居於家中，猶如龍寢息一般。其行為隱藏不施用於世，所以說「寢息之龍，沒有行動」。</p><p>·【易】曰：「亢龍有悔。」孔子曰：「此言為上而驕下，驕下而不殆者，未之有也。聖人之蒞政也，若循木，愈高愈畏下，故曰『亢龍有悔』。」</p><p>譯文：【乾】卦上九曰：『亢龍有悔。』孔子說：『這是說身居於高位而驕慢於下。對臣民驕慢而不危殆的，從未有過。聖人治理國政，好像爬樹，爬得越高就越怕墜落，因此說「龍飛過高，有悔恨」。』</p><p>·【易】曰：「龍戰於野，其血玄黃。」孔子曰：「此言大人之廣德而施教於民也。夫文之理，採彩物畢存者，其唯龍乎？德義廣大，法物備具者，其唯聖人乎？『龍戰於野』者，言大人之廣德而下接民也。『其血玄黃』者，見文也。聖人出法教以導民，亦猶龍之文也，可謂『玄黃』矣，故曰『龍』。見龍而稱莫大焉。」</p><p>譯文：【坤】卦上六曰：『龍戰於野，其血玄黃。』 孔子曰：『此言大人擴充其德而施行教化於民眾。文理色彩全有，大概只有龍吧？德義廣大，治國理政之法度齊備，大概只有聖人吧？所謂「龍戰於野」，是說大人以廣大的德行，下與民眾相接交。「其血玄黃」，就是顯視出文採。聖人制定法度戒令以引導民眾，也就像龍顯現其文采，可稱得上是「玄黃了，因此聖人也可稱為「龍」。出現了龍，沒有比這更好的事情了。</p><p>·【易】曰：「王臣蹇蹇，非今之故。」孔子曰：『王臣蹇蹇』者，言其難也。夫唯知其難也，故重言之，以戒今也。君子知難而備之，則不難矣。見幾而務之，則有功矣。故備難者易，務幾者成，存其人，不言吉兇焉。『非今之故者』，非言獨今也，古已然也。」</p><p>譯文：【蹇】卦六二曰：『王臣蹇蹇，非今之故。』 通行版：【蹇】卦六二曰：『王臣蹇蹇，非躬指自身，非自身的原因之故。』孔子曰：『所謂「王臣蹇蹇」，是說行事之難。正因為知道其艱難，所以重複說成「蹇蹇」，以告誠今世之人。君子知道事情艱難而有充分的準備，就不難了；發現了事情細微的徵兆就立即去做好它，就會取得成功。因此對艱難有準備就容易，發現徵兆就去做就能成功。從事情的微小徵兆做起，無論成功還是失敗都在於做事之人，所以不必講究什麼吉凶了。所謂「非今之故------，不是說今天才是這樣子，自古就是如此。』</p><p>·【易】曰：「鼎折足，覆公莡餗，其形渥，兇。」 孔子曰：「此言下不勝任也。非其任也而任之，能無折乎？下不用則城不守，師不戰，內亂反上，謂『折足』。路其國，蕪其地，五種不收，謂『覆公莡』。口養不至，飢餓不得食，謂『形渥』。」二三子問曰：「人君至於飢乎？」孔子曰：「昔者晉厲公路其國，蕪其地，出田七月不歸，民反諸雲夢。無車而獨行。□□□□□武公□□□□□□□□□焉，不得食其肉，此『其形渥』也。故曰『德義無小，失宗無大』，此之謂也。」</p><p>譯文：【鼎】卦九四日：『鼎折足，覆公鍊，其形渥，兇。』 孔子說：『這是說百姓不能負擔。就像鼎的腿承受不住鼎身一樣，不是百姓能擔負的，而讓他們擔負，能不折斷嗎？臣下不作為，城池不能堅守，軍隊不能作戰，內部動亂反叛君主，就叫作「折足」。使國家貧乏衰敗，土地荒蕪，五穀不收，就叫作「覆公餗」。沒有糧食，飢餓得不到食物，就叫作「形渥」。』二三子問道：『君主都到了飢餓的地步嗎？』孔子說：『過去晉厲公楚靈王使其國家貧困破敗，土地荒蕪，出去打獵七個月不歸，民眾在雲夢乾溪反叛他。他沒有車而獨自徒步行走…吃不到肉，這就是「其形渥」了。所以常語說：「獲得福祥是不論人的地位多麼卑下的，失去宗廟是不論人的地位多麼高貴的。說的就是這個意思。』</p><p>·【易】曰：「鼎玉鼏，大吉，無不利。」孔子曰：「鼎大矣！鼎之遷也，不自往，必人舉之，大人之貞也。鼎之舉也，不以其趾，以□□□□□□□□□□□□□□賢以舉己也。明君蒞政，賢輔闢之，將何為而不利？故曰『大吉』。」</p><p>譯文：【鼎】上九曰：『鼎玉鼏，大吉，無不利。』 孔子說：『鼎體量龐大，鼎在遷移時，不是自己移動，必須有人抬舉它。大人的治國理政，就像鼎的抬舉一樣，不是靠鼎足自己移動，而是靠鼎槓抬舉起來…大人要靠賢者抬舉自己。聖明的君王治國理政，有賢人輔佐他，那麼他要幹什麼事會不順利呢？所以說「大吉」。』</p><p>·【易】曰：「康a侯用錫馬蕃庶，晝日三接。」 孔子曰：「此言聖王之安世者也。聖人之政，牛參弗服，馬恆弗駕，不夏乘牝馬，□□□□□□□□□□粟時至，芻稿不重，故曰『錫馬』。聖人之立政也，必尊天而敬眾，理順五行，天地無災，民□不傷，甘露時雨驟降，飄風苦雨不至，民總相觴以壽，故曰『蕃庶』。聖王各有三公三卿，『晝日三接』者，言□□□者也。」</p><p>譯文：【晉】卦辭曰：『康矦用錫馬番庶，晝日三接。』 孔子說：『這是說聖王使世人安樂的。聖人治國理政，牛幼弱不用於乘駕，馬疲睏不用於駕乘，夏天不乘有孕雌馬…穀類成熟，收割的時機到來，其秸稈飼料新鮮，吃剩的不重複使用，所以說「恩惠賜及於馬」。聖人之臨朝施政，要尊重天時，慎重地對待民眾，要順從木火土金水運行之理。這樣天地沒有災害，民眾不受傷害，甘露和及時雨一齊降下，暴風和淫雨不到來，民眾相互敬重和睦而長壽，所以說「蕃育庶物」。聖王各有三公、三卿，所謂「晝日三接」，是說聖王接見群臣之事。』</p><p>·【易】曰：「括囊，無咎無譽。」 孔子曰：「此言緘小人之口也。小人多言多過，多事多患，□□可以衍矣，而不可以言。緘之，其猶『括囊』也。莫出莫入，故曰『無咎無譽』。」二三子問曰：「獨無緘於聖人之口乎？］孔子曰：「聖人之言也，德之首也。聖人之有口也，猶地之有川穀也，財用所由出也。猶山林陵澤也，衣食庶物所由生也。聖人壹言，萬世用之。唯恐其不言也，有何緘焉？」</p><p>譯文：【坤】卦六四曰：『括囊，無咎無譽。』 孔子說：『這是說約束小人之口的。小人多說話就多過失，多行事就多患難。小人行事不可以饒多，又不要說話。約束他們不言，這就像「扎緊口袋」一樣。不出不入，所以「沒有災害，也沒有榮譽」。』二三子問道：『唯獨不約束聖人之口嗎』孔子說：『聖人所說的話，是德行中最重要的方面。聖人有口，就像地上有川穀，是財用所由出產的地方；好像山林陵澤，是衣食所由産出的地方。聖人的一句話，萬世都用以為真理，並從中得到益處。唯恐聖人不說話啊，有什麼需要約束的呢？』</p><p>·卦曰：「見龍在田，利見大人。」 孔子曰：「此言□□卑謙就民。卑謙，易告也。就民，易遇也。聖人君子之貞也，度民宜之，故曰『利以見大人』。」</p><p>譯文：【乾】卦九二曰：『見龍在田，利見大人。』 孔子曰：『此言大人卑謙親近民眾。大人卑謙，民眾就易於謁見大人；大人親近民眾，民眾就易於逢見大人被重用。聖人、君子之行政，要考慮民眾的適宜，所以說「利於見到大人」。』</p><p>·卦曰：「君子終日乾乾，夕泥若厲，無咎。」孔子曰：「此言君子務時，時至而動，□□□□□屈力以成功，夫日中而不止，時年至而不淹。君子之務時，猶馳驅也，故曰『君子終日乾乾』。時盡而止之，以置身，置身而靜，故曰『夕沂若，厲無咎』。」</p><p>譯文：【乾】九三曰：『君子終日乾乾，夕泥若，厲，無咎。』 孔子曰：『這是說君子抓住時機，時機到了就行動…抓住時機，盡力使所做之事得以成功。到了晚上也不停止，生命到了盡頭也不停留。君子勤奮而不失時機，就像駕車馬快速奔跑一樣，因此說「君子終日勤勉不懈」。時機過去了就停止作為以安身，安身而得寧靜，所以說「晚上停止，危厲，沒有災害」。</p><p>·卦曰：「飛龍在天，利見大人。」孔子曰：「此言君子□□□□□□□君子在上，則民被其利，賢者不蔽，故曰『飛龍在天，利見大人』。」</p><p>譯文：【乾】卦九五曰：『飛龍在天，利見大人。』 孔子說：『這是說君子…君子身居上位，則民眾蒙受他所帶來的利處，賢人不被遮蔽而得到重用，所以說「飛龍在天，利於見到大人」。』</p><p>·卦曰：「見群龍無首，吉。」孔子曰：「龍神威而精，處下而上通其德，『無首』者，□□□□□。『見群龍無首』者，□□君子□□□□□□□□□□□□見君子之吉也。」</p><p>譯文：【乾】卦用九曰：『見群龍無首，吉。』 孔子曰：『龍神妙威嚴精明，處於深淵而上通天德。…』</p><p>卦曰：「履霜，堅冰至。」孔子曰：「此言天時漸，戒保常也。歲始於東北，□於西南。溫始於□，寒始於□□□□□□□□□□□德，與天道始，必順五行，其孫貴而宗不崩。」</p><p>譯文：【坤】初六曰：『履霜，堅冰至。』孔子曰：『這是說天時漸變，告誠永保天道。…聖人或天子行政與天時同其始，一定要順從時令中的五行木、火、土、金、水之序，這樣子孫世世代代才能尊貴，宗廟永不崩滅。』</p><p>·卦曰：「直方大，不習，無不利。」孔子曰：「□□□□□□或也。直者，□避也。方者，□□□□□。大者，言其直或之容焉。□□□□□□□□□□□□□□□□□□□□□□□也。置無不□□，故曰『無不利』。」</p><p>譯文：此章言孔子釋【坤】卦六二爻辭『直方大，不習，無不利』，由於殘缺過甚，其文意不可確知。據殘文推之，此章文字是孔子先解說『直、方、大』三字所包含的義理，其中『大』的含義大約是說君主主持國政時之威儀盛大。君主只要具備了直、方、大三個條件，行事就會無所阻碾，故日『無不利』也。</p><p>·卦曰：「含章可貞，或從王事，無成有終。」</p><p>孔子曰：「含章□□□□□□□□□□□□□含亦美，貞之可也，亦□□□□□無□□□□。或從王事矣。□□□。」</p><p>·卦曰：「黃裳元吉。」孔子曰：「□□□□□元者也。元，善之始也。□□□□不入□□□□下□□□色之徒□□。」</p><p>·卦曰：「屯其膏，小貞吉，大貞兇。」孔子曰：「屯輪……小民家息以接衣食，又有饑□□□時□□□□□□□□屯輪之，其吉亦宜矣。『大貞兇』者，□川流下而貨留高，年？十壹□□□□□□□□□□□□□□□□大人患□□□□□□□□貨，守財弗施則□□□□□□□□□。」</p><p>譯文：【屯】卦九五曰：『屯其膏，小貞吉，大貞兇。』 孔子說：『小民家庭生活以衣食相接續，以防飢餓寒冷，故囤積衣食是吉利的。所謂『大貞兇」，是說大人賦斂無度，河水流動而向下，貨物停留而向上，年收成十取其一…大人仍患其少，而積聚貨物，保守財物而不肯施捨於民眾，會失掉民心，而有兇。</p><p>·卦曰：「同人於野，亨，利涉大川。」孔子曰：「此言大德之好遠也。所行者遠，和同者眾，以濟大事，故曰『利涉大川』。」</p><p>譯文：【同人】卦辭曰：『同人於野，亨，利涉大川。』 孔子說：『此言大德是施行到遠方的。其行於遠方，與其同心合意者要眾多，才能成就大事，故曰「利於涉越大河」。』</p><p>·卦曰：「同人於門，無咎。」孔子曰：「此言其所同唯□□□□□□□□而已矣，小德也，□□之□□□□故曰『無咎』。」</p><p>譯文：【同人】初九日：『同人於門，無咎。』 孔子說：『此言其所和同者僅為鄰近之人，其德僅僅施及門口之外，這是小德…』</p><p>·卦曰：「同人於宗，貞吝。」孔子曰：「此言其所同唯其室人而已矣，□□也，故曰『貞吝』。」</p><p>譯文：【同人】六二曰：『同人於宗，貞吝。』 孔子曰：『此言其所和同者唯其家人而已，這是小德，所以說「佔問有吝惜」。』</p><p>·卦曰：「皎如，威如，吉。」孔子曰：「皎，白也。威，老也。老白之行□□□，故曰『吉』。」</p><p>譯文：【大有】六五曰：『皎如，威如，吉。』 通行版：六五，厥孚交如，威如，吉。孔子曰：『皎，白的意思；威萎，老的意思。此爻辭言年老、滿頭白髮之人的行為…所以說「吉」。』</p><p>·卦曰：「謙，亨，君子有終，吉。」孔子曰：「謙，□卑之□□□吉者□□□□已。其卦上坤而下艮。坤，□□□也。艮，精質也。君子之行也。故□□□□者四吉焉。吉，謙也。兇，驕也。天亂驕而成謙，地徹驕而實謙，鬼神禍驕而福謙，人惡驕而好謙。謙一事而四吉，驕一事而四凶。」</p><p>譯文：【謙】卦辭曰：『謙，亨。君子有終，吉。』 孔子曰：『【謙】卦上為坤，下為艮。坤為柔順，艮為安靜厚實。君子的行為，若遵循謙德，則有四吉。吉利是由於謙虛，兇險是由於驕盈。天亂廢於驕盈而成就於謙虛，地毀壞於驕盈而充實於謙虛，鬼神降禍於驕盈，降福於謙虛，人憎惡於驕盈而喜好於謙虛。謙虛有四種吉利，驕盈有四種兇險。』</p><p>·卦曰：「勞謙，君子有終，吉。」孔子曰：「此言好善不伐也。夫不伐德者，君子也，其盈如不□□□□□，是壹舉而再說，其『有終』也，亦宜矣。」</p><p>譯文：【謙】九三曰：『勞謙，君子有終，吉。』 孔子曰：『這是說喜好行善而不自誇。不自誇其美德的人，君子也。否定盈滿，謙虛而不自誇，這是一種舉動，而有雙重的欣悅。所以爻辭「有好的結果」，是應該的。』</p><p>·卦曰：「盱豫，悔。」孔子曰：「此言鼓樂而不戒患也。夫忘亡者必亡，忘民必憂。□□之□樂□者，所以□，不可□也。故樂至者，其病亦至，不可避。禍福或牽之，□□□□□□□□□□方行，禍福雜至，智者知之，故嚴客恪、愕恐懼，日慎一日，猶有詖行卒至之患，盱豫而不悔□□□也，故曰『悔』。」</p><p>譯文：【豫】六三曰：『盱豫，悔。』 孔子曰：『這是說奏樂而不戒備禍患。忘記危亡者必定減亡，忘記民眾者必定有憂愁。歡樂到來，疾困也隨之而至，不可避免。禍與福又牽連、糾纏，禍與福並行，禍與福集合而至。智者深知其理，故儼正恭敬，心懷恐懼，一天比一天謹慎。但即使這樣，仍然有偏頗之行和猝然而至之禍患。過分豫樂而不知節制，所以說「有悔恨」。</p><p>·卦曰：「鳴鶴在陰，其子和之，我有好爵，與爾羸靡之。」孔子曰：「鳴□□□□□□□□□其子隨之，通也。唱而和之，和也。曰：和同，至矣。『好爵』者，言旨酒也。我有一爵，與眾共之，德之□者也。□□□□來吉會□之德，唯飲與食，絕甘分少，□□□。」</p><p>譯文：【中孚】九二曰：『鳴鶴在陰，其子和之。我有好爵，與爾靡之。』 孔子曰：『…小鶴隨其大鶴，這是心靈相通。大鶴鳴叫，小鶴應和，這是和樂。所以說和樂同心，達到極點了。「好爵」，是說美酒。我有一杯美酒，與眾人共同分享它。…唯有飲食，有甘美的就全讓出，自己一點不吃，有少量的分給大家一起吃，即所謂「與爾靡之」。</p><p>·卦曰：「密雲不雨，自我西郊，公射取彼在穴。」孔子曰：「此言聖君之下舉乎山林畎畝之中也，故曰『公射取皮在穴』。」</p><p>譯文：【小過】六五曰：『密雲不雨，自我西郊，公弋取彼在穴。』 孔子曰：『這是說聖明的君主是從在野民間推舉、舉薦出來的，所以說「公射鳥，取自於洞穴」。』</p><p>·卦曰：「恆，亨，無咎，利貞也。」孔子曰：「恆者，□□□□□□者恆其德，其德□長，故曰『利貞』。其佔曰：『好善不留，□□□□。』其貞亦宜矣。」</p><p>譯文：【恆】卦辭曰：『恆，亨，無咎，利貞。』 孔子曰：『恆謂恆守其德，其德恆久，所以說「利於守正」。其佔辭說：「好善不留…」所以其「亨通」是應該的。』</p><p>·卦曰：「不恆其德，或承之羞，貞吝。」孔子曰：「此言小人知善而弗為，方進而無止，損幾則釋矣，能無羞乎？故曰『貞閵』。」</p><p>譯文：【恆】卦九三曰：『不恆其德，或承之憂，貞吝。』 孔子曰：『這是說小人知道美善而不去做，當進而停止，放棄時機，縱其流失，能不憂患嗎？所以說「佔問有吝」。』</p><p>·卦曰：「大蹇，朋來。］孔子曰：「此言□□也。飭行以後民者謂『大蹇』，遠人偕至謂［朋來］。」</p><p>譯文：【蹇】卦九五曰：『大蹇朋來。』 孔子曰：『這是說…修正自己的行為，將自身利益置於民眾之後對君主是很艱難的，所以說『十分艱難」。遠方之人一起到來，所以說「朋友到來」。』</p><p>·卦曰：「公用射鵻隼於高墉之上，無不利。」孔子曰：「此言人君高志求賢。賢者在上，則因尊用之，故曰『射鵻於高墉之上』。」</p><p>譯文：【解】卦上六曰：『公用射隼於高墉之上，無不利。』 孔子日：『這是說君主具高遠志向，尋求賢者。賢者高居眾俗之上，要依靠尊重他們，而使用他們，所以說「射鷹隼於高大的城牆之上」。』</p><p>·卦曰：「艮其北，不獲其身。行其庭，不見其人。」孔子曰：「『艮其北』者，言任事也。『不獲其身』者，精白□□□也。敬官任事，身【不】得者鮮矣。其佔曰：『能精能白，必為上客。能白能精，必為古正。』以精白長眾者難得也，故曰『行其庭，不見其人』。」</p><p>譯文：【艮】卦辭曰：『艮其背，不獲其身；行其庭，不見其人。』 孔子曰：『「靜止其背」，是說擔任事務。「不得到其身」，是說修其心，致心潔白，使精充盈。敬修其心，而擔任事務，不能得到其身的很少了。其佔辭說：「能充盈其精，能潔白其心，必為大臣。能潔白其心，能充盈其精，必為高官。」以修養達到精白境地而為民眾之長，是很難得的，所以說「行走在庭院，不見到人。」』</p><p>·卦曰：「艮其輔，言有序。」孔子曰：「慎言也。吉凶之至也，必皆於言語。釋善而言惡，釋利而言害，塞人之美，揚人之過，可謂無德，其兇亦宜矣。君子慮之內，發之口，言義不言不義，言利不言害，塞人之惡，揚人之美，可謂『有序』矣。」</p><p>譯文：【良】卦六五曰：『良其輔，言有序。』 孔子曰：『這是說要謹慎地對待言談。吉凶的來臨，一定是以言談為契機的。不談善而談不善，不談利而談害，掩蓋別人的美善，宣揚別人的過錯，可以說是沒有德行，獲得兇也是應該的了。君子深思熟慮於內心，發言於口，說應當說的，不說不應當說的，說有利的，不說有害的，掩蓋別人的過錯，宣揚別人的美善，可以說「言談有條理」了。』</p><p>·卦曰：「豐，亨，王叚假、格之，勿憂，宜日中。」孔子曰：「豐，大□也。勿憂，用賢弗害也。日中而盛，用賢弗害，其亨亦宜矣。黃帝四輔，堯立三卿，帝王者之處盛也長。故曰『宜日中』。」</p><p>譯文：【豐】卦辭曰：『豐，亨通，君王到來，不要憂慮，宜於太陽位居中天時。』 孔子曰：『「豐」是大的意思。「不要憂慮」，是起用賢人而不以為忌患。太陽到中午最為盛大，君主起用賢人而不以為忌害，其「亨通」是應該的。如黃帝起用四位輔助者，堯設立三卿，這樣君王處於盛大就能長久，所以說「宜於日中」。』</p><p>·卦曰：「奐其肝，大號。」孔子曰：「奐，大美也。肝，言其內，其內大美，其外必有大聲聞。」</p><p>譯文：【渙】卦九五曰：『奐其肝，大號。』 孔子曰：『「奐」，是大美的意思。「肝」，是說內。其內大美，其外必有好名聲。』</p><p>·卦曰：「未濟，亨。小狐涉川，幾濟，濡其尾，無攸利。」孔子曰：「此言始易而終難也，小人之貞也。」</p><p>譯文：【未濟】卦辭曰：『未濟卦，亨通，小狐狸渡河，幾乎就要渡過去，沾濕尾巴，無所有利。』 孔子曰：『這是說開始容易，終結艱難，這是小人的固守拘泥呀。』</p>",76)])])}const f=t(o,[["render",_]]);export{m as __pageData,f as default};
